#include <net-snmp/net-snmp-config.h>
#include <net-snmp/net-snmp-includes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("usage: %s <config-file>\n", argv[0]);
        return 1;
    }
    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, fp);
    buf[sz] = '\0';
    fclose(fp);

    printf("Config length: %ld\n", sz);
    printf("First 20: %.20s\n", buf);
    printf("Last 20: %.20s\n", buf + sz - 20);

    // Test sscanf directly
    int value;
    char e_enum[8192];
    const char *cp = copy_nword_const(buf + 4, e_enum, sizeof(e_enum));
    printf("e_enum[0]=%c e_enum[1]=%c e_enum[8190]=%c e_enum[8191]=%d\n", 
           e_enum[0], e_enum[1], e_enum[8190], e_enum[8191]);
    int ret = sscanf(e_enum, "%d:", &value);
    printf("sscanf ret=%d value=%d\n", ret, value);

    printf("Calling se_read_conf\n");
    se_read_conf("enum", buf);
    printf("Returned from se_read_conf\n");
    free(buf);
    return 0;
}
EOF
